static int hash256(const void*d,size_t n,char out[65]){unsigned char h[32];unsigned z=0;EVP_MD_CTX*c=EVP_MD_CTX_new();if(!c)return-1;int ok=EVP_DigestInit_ex(c,EVP_sha3_256(),NULL)==1&&EVP_DigestUpdate(c,d,n)==1&&EVP_DigestFinal_ex(c,h,&z)==1&&z==32;EVP_MD_CTX_free(c);if(!ok)return-1;static const char*x="0123456789abcdef";for(int i=0;i<32;i++){out[i*2]=x[h[i]>>4];out[i*2+1]=x[h[i]&15];}out[64]=0;return 0;}
