static int readall(const char*p,unsigned char**out,size_t*n){FILE*f=fopen(p,"rb");if(!f)return-1;if(fseek(f,0,SEEK_END)){fclose(f);return-1;}long z=ftell(f);if(z<0||fseek(f,0,SEEK_SET)){fclose(f);return-1;}unsigned char*b=malloc(z?z:1);if(!b){fclose(f);return-1;}if(z&&fread(b,1,z,f)!=(size_t)z){free(b);fclose(f);return-1;}fclose(f);*out=b;*n=(size_t)z;return 0;}
