static int qrx_file_copy_stream(const char*src,const char*dst,uint64_t*size_out){FILE*a=fopen(src,"rb");if(!a)return-1;FILE*b=fopen(dst,"wb");if(!b){fclose(a);return-1;}unsigned char buf[128*1024];uint64_t total=0;int rc=0;for(;;){size_t n=fread(buf,1,sizeof(buf),a);if(n){if(fwrite(buf,1,n,b)!=n){rc=-1;break;}total+=n;}if(n<sizeof(buf)){if(ferror(a))rc=-1;break;}}if(fflush(b)||fclose(b))rc=-1;fclose(a);if(rc)remove(dst);else if(size_out)*size_out=total;return rc;}
